from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    separate_groups = []
    group = ""
    open_count = 0

    for char in paren_string:
        if char == "(":
            open_count += 1
            if open_count == 1:
                group += char
        elif char == ")":
            open_count -= 1
            if open_count == 0:
                group += char
                separate_groups.append(group)
                group = ""
        else:
            if open_count > 0:
                group += char

    return separate_groups

